#!/bin/sh
set -eu

############################################################################
# PassWall SOCKS5 Batch / DNS 扩展
# V2 重整理版：保持原有功能与资源，主要优化结构、锁、状态与可读性。
############################################################################
SCRIPT_NAME="PassWall-SOCKS5-batch"
SCRIPT_VERSION="2.0.0"
INSTALL_STATE="/root/passwall-socks5-batch.install-state"
LOCK_DIR="/tmp/passwall-socks5-batch.lock"
LOCK_HELD=0



############################################################################
# 路径与状态常量
############################################################################
CONTROLLER="/usr/lib/lua/luci/controller/passwall_socks_batch.lua"
MODEL="/usr/lib/lua/luci/model/cbi/passwall/client/socks_batch.lua"
LAN_MODEL="/usr/lib/lua/luci/model/cbi/passwall/client/lan_batch.lua"
LAN_DELETE="/usr/lib/lua/luci/model/cbi/passwall/client/lan_delete.lua"
SOCKS_DELETE="/usr/lib/lua/luci/model/cbi/passwall/client/socks_delete.lua"
XRAY_UTIL="/usr/lib/lua/luci/passwall/util_xray.lua"
SERVER_INDEX="/usr/lib/lua/luci/model/cbi/passwall/server/index.lua"
SERVER_UNINSTALL="/usr/lib/lua/luci/view/passwall/server/uninstall_extension.htm"
MENU_JSON="/usr/share/luci/menu.d/luci-app-passwall-socks5-batch.json"
NODE_LIST="/usr/lib/lua/luci/view/passwall/node_list/node_list.htm"
NFTABLES_SH="/usr/share/passwall/nftables.sh"
SING_BOX_UTIL="/usr/lib/lua/luci/passwall/util_sing-box.lua"
ORIGINAL_SUFFIX=".bak.passwall-socks5-batch.original"
UNINSTALLED_MARKER="/root/passwall-socks5-batch.uninstalled"

############################################################################
# 基础工具
############################################################################
log() {
    echo "[PassWall-SOCKS5] $*"
}

acquire_lock() {
    if mkdir "$LOCK_DIR" 2>/dev/null; then
        LOCK_HELD=1
        return 0
    fi
    fail "检测到另一个 PassWall 安装/更新任务正在运行：$LOCK_DIR"
}

release_lock() {
    if [ "$LOCK_HELD" = 1 ]; then
        rm -rf "$LOCK_DIR"
        LOCK_HELD=0
    fi
}

write_install_state() {
    _state_dir="$(dirname "$INSTALL_STATE")"
    mkdir -p "$_state_dir"
    cat > "$INSTALL_STATE" <<EOF
SCRIPT_NAME=$SCRIPT_NAME
SCRIPT_VERSION=$SCRIPT_VERSION
INSTALLED_AT=$(date '+%Y-%m-%d %H:%M:%S')
EOF
}

fail() {
    echo "错误：$*" >&2
    exit 1
}

clear_luci_cache() {
    for file in /tmp/luci-indexcache*; do
        [ -f "$file" ] && rm -f "$file"
    done
    rm -rf /tmp/luci-modulecache
    (sleep 2; /etc/init.d/uhttpd reload) </dev/null >/dev/null 2>&1 &
}

install_runtime_asset() {
    asset_dir="$1"
    name="$2"
    target="$3"
    mode="$4"
    source_file="$asset_dir/$name"

    [ -s "$source_file" ] || fail "离线资源缺失：$name"
    mkdir -p "$(dirname "$target")"
    save_original_file "$target" "$target.bak.oneclick.*" "" "$source_file"
    cp "$source_file" "$target"
    chmod "$mode" "$target"
}

save_original_file() {
    original_target="$1"
    original_pattern="$2"
    original_backup="$original_target$ORIGINAL_SUFFIX"
    [ ! -e "$original_backup" ] || return 0
    [ ! -e "$original_backup.absent" ] || return 0
    # 旧版备份可能只是上一版扩展；同名的非扩展文件以当前文件为准。
    original_oldest=""
    if [ "${WAS_UNINSTALLED:-0}" != 1 ]; then
        original_oldest="$(ls -1 $original_pattern 2>/dev/null | head -n 1 || true)"
    fi
    if [ -n "$original_oldest" ]; then
        if [ -n "${4:-}" ] && cmp -s "$original_oldest" "$4"; then
            if [ -f "$original_target" ] &&
                ! cmp -s "$original_target" "$4"; then
                cp -p "$original_target" "$original_backup"
            else
                touch "$original_backup.absent"
            fi
        elif [ -n "${3:-}" ] && grep -Fq "$3" "$original_oldest"; then
            if [ -f "$original_target" ] &&
                ! grep -Fq "$3" "$original_target"; then
                cp -p "$original_target" "$original_backup"
            else
                touch "$original_backup.absent"
            fi
        else
            cp -p "$original_oldest" "$original_backup"
        fi
    elif [ -f "$original_target" ]; then
        cp -p "$original_target" "$original_backup"
    else
        touch "$original_backup.absent"
    fi
}

install_runtime_assets() {
    asset_dir="$1"
    install_runtime_asset "$asset_dir" "passwall-node-list.htm" \
        "$NODE_LIST" 644
    install_runtime_asset "$asset_dir" "passwall-nftables.sh" \
        "$NFTABLES_SH" 755
    install_runtime_asset "$asset_dir" "passwall-util_sing-box.lua" \
        "$SING_BOX_UTIL" 644

    # 持久保存 PassWall 原始节点列表模板，供卸载时可靠还原
    mkdir -p /etc/passwall-socks5-batch/original
    if [ -s "$NODE_LIST$ORIGINAL_SUFFIX" ] &&
        [ ! -s /etc/passwall-socks5-batch/original/node_list.htm ]; then
        cp -p "$NODE_LIST$ORIGINAL_SUFFIX" /etc/passwall-socks5-batch/original/node_list.htm
    fi
}


############################################################################
# SOCKS5 / PassWall 全局代理修复
############################################################################
fix_sk5() {
    dns="${1:-223.5.5.5}"
    [ "$(id -u)" = "0" ] || fail "请使用 root 运行"
    [ -f "/etc/config/passwall" ] || fail "未检测到 PassWall"
    validate_dns "$dns"
    require_clean_uci passwall

    stamp="$(date +%Y%m%d-%H%M%S)"
    backup="/root/passwall.bak.sk5fix.$stamp"
    cp -p /etc/config/passwall "$backup"

    uci set passwall.@global[0].enabled='1'
    uci set passwall.@global[0].use_gfw_list='0'
    uci set passwall.@global[0].chn_list='0'
    uci set passwall.@global[0].tcp_proxy_mode='proxy'
    uci set passwall.@global[0].udp_proxy_mode='proxy'
    uci set passwall.@global[0].tcp_proxy_way='redirect'
    uci set passwall.@global_forwarding[0].tcp_proxy_way='redirect'
    uci set passwall.@global_forwarding[0].prefer_nft='1'
    uci set passwall.@global[0].dns_redirect='1'
    uci set passwall.@global[0].dns_shunt='chinadns-ng'
    uci set passwall.@global[0].dns_mode='tcp'
    uci set passwall.@global[0].direct_dns_mode='tcp'
    uci set passwall.@global[0].direct_dns="$dns"
    uci set passwall.@global[0].remote_dns="$dns"
    uci commit passwall

    [ "$(uci -q get passwall.@global[0].use_gfw_list)" = "0" ] ||
        fail "GFW 列表关闭失败"
    [ "$(uci -q get passwall.@global[0].chn_list)" = "0" ] ||
        fail "中国列表关闭失败"
    [ "$(uci -q get passwall.@global[0].tcp_proxy_mode)" = "proxy" ] ||
        fail "TCP 全局代理设置失败"
    [ "$(uci -q get passwall.@global_forwarding[0].tcp_proxy_way)" = "redirect" ] ||
        fail "TCP 转发方式设置失败"
    [ "$(uci -q get passwall.@global[0].udp_proxy_mode)" = "proxy" ] ||
        fail "UDP 全局代理设置失败"
    [ "$(uci -q get passwall.@global[0].direct_dns)" = "$dns" ] ||
        fail "直连 DNS 设置失败"
    [ "$(uci -q get passwall.@global[0].remote_dns)" = "$dns" ] ||
        fail "远程 DNS 设置失败"

    /etc/init.d/passwall restart

    echo "SOCKS5 全局 TCP/UDP 代理模式已启用。"
    echo "DNS：$dns（TCP）"
    echo "TCP/UDP：全局经过 SOCKS5"
    echo "备份：$backup"
}

fix_xray_source_rules() {
    [ -f "$XRAY_UTIL" ] || return 0
    grep -Fq \
        'if not domains and not ip and (protocols or source) then' \
        "$XRAY_UTIL" && return 0
    grep -Fq 'if not domains and not ip and protocols then' "$XRAY_UTIL" ||
        fail "Xray 分流规则兼容补丁无法应用：PassWall 版本不匹配"

    save_original_file "$XRAY_UTIL" "$XRAY_UTIL.bak.lanbatch.*"
    sed -i \
        's/if not domains and not ip and protocols then/if not domains and not ip and (protocols or source) then/' \
        "$XRAY_UTIL"
    grep -Fq \
        'if not domains and not ip and (protocols or source) then' \
        "$XRAY_UTIL" ||
        fail "Xray 分流规则兼容补丁写入失败"
    lua -e "assert(loadfile('$XRAY_UTIL'))" ||
        fail "修改后的 util_xray.lua 语法检查失败"
}


############################################################################
# DNS 防泄漏
############################################################################
DNS_LEAK_PREFIX="PassWall DNS Leak Protection"
DNS_LEAK_NFT="/etc/nftables.d/90-passwall-dns-leak.nft"
DNS_LEAK_BACKUP="/root/passwall-firewall.bak.dnsleak"

validate_dns() {
    dns="$1"
    printf '%s\n' "$dns" | awk -F. '
        NR != 1 || NF != 4 { exit 1 }
        { for (i = 1; i <= 4; i++)
            if ($i !~ /^[0-9]+$/ || $i < 0 || $i > 255) exit 1 }
        END { if (NR != 1) exit 1 }' ||
        fail "DNS 地址无效：$dns（当前仅接受 IPv4 DNS）"
}

require_clean_uci() {
    for config in "$@"; do
        pending="$(uci -q changes "$config")" ||
            fail "无法检查 $config 的待提交修改"
        [ -z "$pending" ] ||
            fail "$config 有待提交修改，请先保存或撤销后重试"
    done
}

dns_leak_remove_uci() {
    [ -f /etc/config/firewall ] || return 0
    # 每删除一条后重新读取匹配项，避免 uci 索引随删除前移而漏删/误删。
    while :; do
        section="$(uci -q show firewall | sed -n "s/^firewall\.\([^=]*\)\.name='${DNS_LEAK_PREFIX}[^']*'$/\1/p" | head -n 1)"
        [ -n "$section" ] || break
        uci -q delete "firewall.$section" || return 1
    done
}

dns_leak_remove_nft() {
    rm -f "$DNS_LEAK_NFT"
}

dns_leak_apply() {
    dns_leak_remove_uci || return 1
    dns_leak_remove_nft || return 1
    family=ipv4
    command -v fw4 >/dev/null 2>&1 && family=any

    # 53 端口：强制 LAN 客户端回到路由器本地 DNS。
    # PassWall 自身的 dns_redirect=1 再负责把 DNS 交给 PassWall DNS 链路。
    sec="$(uci add firewall redirect)" || return 1
    uci set "firewall.$sec.name=$DNS_LEAK_PREFIX - DNS53" || return 1
    uci set "firewall.$sec.src=lan" || return 1
    uci set "firewall.$sec.proto=tcp udp" || return 1
    uci set "firewall.$sec.src_dport=53" || return 1
    uci set "firewall.$sec.dest_port=53" || return 1
    uci set "firewall.$sec.target=DNAT" || return 1
    uci set "firewall.$sec.family=$family" || return 1

    # DoT/DoQ：阻止客户端绕过本地 DNS，直接连接外部 853 端口。
    sec="$(uci add firewall rule)" || return 1
    uci set "firewall.$sec.name=$DNS_LEAK_PREFIX - Block DoT TCP853" || return 1
    uci set "firewall.$sec.src=lan" || return 1
    uci set "firewall.$sec.dest=wan" || return 1
    uci set "firewall.$sec.proto=tcp" || return 1
    uci set "firewall.$sec.dest_port=853" || return 1
    uci set "firewall.$sec.target=REJECT" || return 1
    uci set "firewall.$sec.family=$family" || return 1

    sec="$(uci add firewall rule)" || return 1
    uci set "firewall.$sec.name=$DNS_LEAK_PREFIX - Block DoQ UDP853" || return 1
    uci set "firewall.$sec.src=lan" || return 1
    uci set "firewall.$sec.dest=wan" || return 1
    uci set "firewall.$sec.proto=udp" || return 1
    uci set "firewall.$sec.dest_port=853" || return 1
    uci set "firewall.$sec.target=REJECT" || return 1
    uci set "firewall.$sec.family=$family" || return 1

    uci commit firewall || return 1
    /etc/init.d/firewall reload >/dev/null 2>&1 || return 1

    # 同时开启 PassWall 的 DNS 劫持；已有设置保持兼容。
    uci set passwall.@global[0].dns_redirect='1' || return 1
    uci set passwall.@global[0].direct_dns_mode='tcp' || return 1
    uci set passwall.@global[0].remote_dns="$1" || return 1
    uci set passwall.@global[0].direct_dns="$1" || return 1
    uci commit passwall || return 1
    /etc/init.d/passwall restart >/dev/null 2>&1 || return 1
}

dns_leak_snapshot() {
    dns_backup_dir="$(mktemp -d /tmp/passwall-dns-leak.XXXXXX)" ||
        fail "无法创建 DNS 配置备份目录"
    cp -p /etc/config/firewall "$dns_backup_dir/firewall" ||
        fail "备份防火墙配置失败，临时目录：$dns_backup_dir"
    if [ "${1:-}" != firewall_only ] && [ -f /etc/config/passwall ]; then
        cp -p /etc/config/passwall "$dns_backup_dir/passwall" ||
            fail "备份 PassWall 配置失败，临时目录：$dns_backup_dir"
    fi
    if [ -f "$DNS_LEAK_NFT" ]; then
        cp -p "$DNS_LEAK_NFT" "$dns_backup_dir/nft" ||
            fail "备份 nftables 规则失败，临时目录：$dns_backup_dir"
    fi
}

dns_leak_restore() {
    rollback_failed=0
    uci revert firewall >/dev/null 2>&1 || rollback_failed=1
    if [ -f "$dns_backup_dir/passwall" ]; then
        uci revert passwall >/dev/null 2>&1 || rollback_failed=1
    fi
    cp -p "$dns_backup_dir/firewall" /etc/config/firewall || rollback_failed=1
    if [ -f "$dns_backup_dir/passwall" ]; then
        cp -p "$dns_backup_dir/passwall" /etc/config/passwall || rollback_failed=1
    fi
    if [ -f "$dns_backup_dir/nft" ]; then
        cp -p "$dns_backup_dir/nft" "$DNS_LEAK_NFT" || rollback_failed=1
    else
        rm -f "$DNS_LEAK_NFT" || rollback_failed=1
    fi
    /etc/init.d/firewall reload >/dev/null 2>&1 || rollback_failed=1
    if [ -f "$dns_backup_dir/passwall" ]; then
        /etc/init.d/passwall restart >/dev/null 2>&1 || rollback_failed=1
    fi
    [ "$rollback_failed" -eq 0 ]
}

dns_leak_enable() {
    dns="${1:-223.5.5.5}"
    validate_dns "$dns"
    [ -f /etc/config/firewall ] || fail "未检测到 /etc/config/firewall，无法启用 DNS 防泄漏"
    [ -f /etc/config/passwall ] || fail "未检测到 /etc/config/passwall"
    require_clean_uci firewall passwall
    dns_leak_snapshot
    cp -p /etc/config/firewall "${DNS_LEAK_BACKUP}.$(date +%Y%m%d-%H%M%S)" || {
        rm -rf "$dns_backup_dir"
        fail "备份防火墙配置失败"
    }

    if ! dns_leak_apply "$dns"; then
        if ! dns_leak_restore; then
            fail "DNS 防泄漏启用失败，自动恢复不完整，备份位于 $dns_backup_dir"
        fi
        rm -rf "$dns_backup_dir"
        fail "DNS 防泄漏启用失败，已恢复防火墙和 PassWall 配置"
    fi
    rm -rf "$dns_backup_dir"

    echo "DNS 防泄漏：已启用"
    echo "LAN TCP/UDP 53：强制回本机 DNS"
    echo "LAN TCP/UDP 853：阻止外部 DoT/DoQ"
    echo "PassWall DNS：$dns"
}

dns_leak_disable() {
    [ "$(id -u)" = "0" ] || fail "请使用 root 运行"
    [ -f /etc/config/firewall ] || fail "未检测到 /etc/config/firewall"
    require_clean_uci firewall
    dns_leak_snapshot firewall_only
    if ! dns_leak_remove_uci || ! dns_leak_remove_nft ||
       ! uci commit firewall ||
       ! /etc/init.d/firewall reload >/dev/null 2>&1; then
        if ! dns_leak_restore; then
            fail "DNS 防泄漏关闭失败，自动恢复不完整，备份位于 $dns_backup_dir"
        fi
        rm -rf "$dns_backup_dir"
        fail "DNS 防泄漏关闭失败，已恢复防火墙配置"
    fi
    rm -rf "$dns_backup_dir"
    echo "DNS 防泄漏防火墙规则已移除。"
    echo "注意：不会自动关闭 PassWall 原有 dns_redirect 设置。"
}


############################################################################
# 文件恢复与卸载
############################################################################
restore_original_file() {
    target="$1"
    pattern="$2"
    original="$target$ORIGINAL_SUFFIX"
    if [ -f "$original" ]; then
        cp -p "$original" "$target"
    elif [ -f "$original.absent" ]; then
        rm -f "$target"
    else
        oldest="$(ls -1 $pattern 2>/dev/null | head -n 1 || true)"
        if [ -n "$oldest" ]; then
            if [ -n "${3:-}" ] && grep -Fq "$3" "$oldest"; then
                if [ ! -f "$target" ] || grep -Fq "$3" "$target"; then
                    rm -f "$target"
                fi
            else
                cp -p "$oldest" "$target"
            fi
        fi
    fi
}

uninstall_extension() {
    [ "$(id -u)" = "0" ] || fail "请使用 root 运行"
    if [ -f "$UNINSTALLED_MARKER" ] &&
        [ ! -e "$CONTROLLER$ORIGINAL_SUFFIX" ] &&
        [ ! -e "$CONTROLLER$ORIGINAL_SUFFIX.absent" ] &&
        { [ ! -f "$CONTROLLER" ] ||
          ! grep -Fq 'function socks_uninstall()' "$CONTROLLER"; }; then
        echo "扩展已卸载。"
        return 0
    fi
    uninstall_stamp="$(date +%Y%m%d-%H%M%S)"
    backup_dir="$(mktemp -d "/root/passwall-extension.removed.$uninstall_stamp.XXXXXX")" ||
        fail "无法创建卸载备份目录"

    for file in "$CONTROLLER" "$MODEL" "$LAN_MODEL" "$SERVER_UNINSTALL" \
        "$LAN_DELETE" "$SOCKS_DELETE" "$MENU_JSON" "$NODE_LIST" \
        "$NFTABLES_SH" "$SING_BOX_UTIL" "$XRAY_UTIL" "$SERVER_INDEX"; do
        [ ! -f "$file" ] || cp -p "$file" "$backup_dir/"
    done

    restore_original_file "$CONTROLLER" "$CONTROLLER.bak.*" \
        'module("luci.controller.passwall_socks_batch"'
    restore_original_file "$MODEL" "$MODEL.bak.*" 'SimpleForm("socks_batch"'
    restore_original_file "$LAN_MODEL" "$LAN_MODEL.bak.*" 'SimpleForm("lan_batch"'
    restore_original_file "$LAN_DELETE" "$LAN_DELETE.bak.*" 'SimpleForm("lan_delete"'
    restore_original_file "$SOCKS_DELETE" "$SOCKS_DELETE.bak.*" 'SimpleForm("socks_delete"'
    restore_original_file "$SERVER_UNINSTALL" "$SERVER_UNINSTALL.bak.*" \
        'pw-server-uninstall-extension'
    restore_original_file "$MENU_JSON" "$MENU_JSON.bak.*" \
        '"admin/services/passwall/socks_batch"'
    restore_original_file "$NODE_LIST" \
        "$NODE_LIST.bak.oneclick.*"
    if [ ! -s "$NODE_LIST" ]; then
        mkdir -p "$(dirname "$NODE_LIST")"
        if [ -s /etc/passwall-socks5-batch/original/node_list.htm ]; then
            cp -p /etc/passwall-socks5-batch/original/node_list.htm "$NODE_LIST"
