    fi
    restore_original_file "$NFTABLES_SH" \
        "$NFTABLES_SH.bak.oneclick.*"
    restore_original_file "$SING_BOX_UTIL" \
        "$SING_BOX_UTIL.bak.oneclick.*"
    restore_original_file "$XRAY_UTIL" \
        "$XRAY_UTIL.bak.lanbatch.*"
    restore_original_file "$SERVER_INDEX" \
        "$SERVER_INDEX.bak.uninstallext.*"

    if [ ! -f "$SERVER_INDEX$ORIGINAL_SUFFIX" ] &&
        [ ! -f "$SERVER_INDEX$ORIGINAL_SUFFIX.absent" ] &&
        [ -f "$SERVER_INDEX" ] &&
        grep -Fq '/server/uninstall_extension' "$SERVER_INDEX"; then
        sed -i '/\/server\/uninstall_extension/d' "$SERVER_INDEX"
    fi

    for file in "$CONTROLLER" "$MODEL" "$LAN_MODEL" "$LAN_DELETE" \
        "$SOCKS_DELETE" "$SERVER_UNINSTALL" "$MENU_JSON" "$NODE_LIST" \
        "$NFTABLES_SH" "$SING_BOX_UTIL" "$XRAY_UTIL" "$SERVER_INDEX"; do
        rm -f "$file$ORIGINAL_SUFFIX" "$file$ORIGINAL_SUFFIX.absent"
    done
    rm -f /root/passwall-socks5-batch.install-state
    touch "$UNINSTALLED_MARKER"
    clear_luci_cache
    /etc/init.d/passwall restart >/dev/null 2>&1 || true

    echo "扩展已卸载，节点和分流规则已保留。"
    echo "卸载前文件备份：$backup_dir"
}


############################################################################
# 命令行入口
############################################################################
case "${1:-}" in
    -h|--help)
        cat <<'EOF'
PassWall 节点管理扩展安装脚本

用法：
  sh passwall-socks5-batch.sh             安装或更新
  sh passwall-socks5-batch.sh --uninstall 卸载扩展并保留节点配置
  sh passwall-socks5-batch.sh --fix-sk5 [DNS]
                                          修复 SOCKS5 的 DNS 和 UDP 兼容性
                                          默认 DNS：223.5.5.5
  sh passwall-socks5-batch.sh --dns-leak [DNS]
                                          启用 DNS 防泄漏
  sh passwall-socks5-batch.sh --dns-leak-off
                                          移除本脚本添加的 DNS 防泄漏规则

安装后进入：
  服务 -> PassWall -> 节点管理
  服务 -> PassWall -> 批量导入分流规则
卸载不会删除已经导入的节点。
EOF
        exit 0
        ;;
    --fix-sk5)
        fix_sk5 "${2:-223.5.5.5}"
        exit 0
        ;;
    --dns-leak)
        [ "$(id -u)" = "0" ] || fail "请使用 root 运行"
        [ -f "/etc/config/passwall" ] || fail "未检测到 PassWall"
        dns_leak_enable "${2:-223.5.5.5}"
        exit 0
        ;;
    --dns-leak-off)
        dns_leak_disable
        exit 0
        ;;
    --uninstall)
        uninstall_extension
        exit 0
        ;;
    "")
        ;;
    *)
        fail "未知参数：$1，使用 --help 查看帮助"
        ;;
esac

[ "$(id -u)" = "0" ] || fail "请使用 root 运行"
acquire_lock
trap 'release_lock; rm -rf "$tmp_dir"' EXIT HUP INT TERM
command -v lua >/dev/null 2>&1 || fail "未找到 Lua"
[ -f "/etc/config/passwall" ] || fail "未检测到 PassWall"
[ -f "/usr/lib/lua/luci/passwall/api.lua" ] ||
    fail "仅支持传统 PassWall，不支持 PassWall2"
[ -f "/usr/lib/lua/luci/model/cbi/passwall/client/shunt_rules.lua" ] ||
    fail "当前 PassWall 不支持 Sing-Box/Xray 分流规则"
[ -f "$SERVER_INDEX" ] || fail "未找到 PassWall 服务端页面"
[ -f /etc/config/firewall ] || fail "未检测到 /etc/config/firewall"
if [ -f "$XRAY_UTIL" ] &&
    ! grep -Fq 'if not domains and not ip and (protocols or source) then' "$XRAY_UTIL" &&
    ! grep -Fq 'if not domains and not ip and protocols then' "$XRAY_UTIL"; then
    fail "Xray 分流规则兼容补丁无法应用：PassWall 版本不匹配"
fi
if ! grep -Fq '/server/uninstall_extension' "$SERVER_INDEX" &&
    ! grep -Fq 'return api.return_map(m)' "$SERVER_INDEX"; then
    fail "PassWall 服务端页面缺少扩展挂载点"
fi
require_clean_uci passwall firewall


############################################################################
# 安装临时目录与离线资源
############################################################################
WAS_UNINSTALLED=0
[ ! -f "$UNINSTALLED_MARKER" ] || WAS_UNINSTALLED=1
tmp_dir="$(mktemp -d /tmp/passwall-socks5-batch.XXXXXX)" ||
    fail "无法创建安全的临时目录"
trap 'release_lock; rm -rf "$tmp_dir"' EXIT HUP INT TERM

# 资源布局：
#   1. 离线资源：LuCI / nftables / sing-box 等基础文件
#   2. 基础安装：菜单、页面、节点管理、SOCKS5、DNS 防泄漏
#   3. 二阶段更新：DNS 检测、节点检测、守护进程、UI 增强
#   4. 最终状态：写入安装状态并释放锁
# BEGIN OFFLINE ASSETS
command -v base64 >/dev/null 2>&1 || fail "离线包需要系统自带 base64"
mkdir -p "$tmp_dir/assets"
