cat >"$tmp_dir/server_uninstall_extension.htm" <<'EOF'
<%
local map = self.map
local api = map.api
-%>
<fieldset class="cbi-section" id="pw-extension-management">
    <legend>扩展管理</legend>
    <div style="padding:12px 0;text-align:center">
        <button id="pw-server-uninstall-extension" type="button"
            style="padding:7px 18px;border:0;border-radius:4px;
            background:#e53935;color:#fff;cursor:pointer;min-width:120px">
            卸载扩展
        </button>
        <div style="margin-top:8px;opacity:.72;font-size:.9em">
            无需手动关闭 PassWall。移除扩展后会自动重启服务，并保留现有节点、分流规则与主配置。
        </div>
    </div>
</fieldset>
<script>
(function() {
    function showDialog(message, onOk) {
        var overlay = document.createElement("div");
        overlay.style.cssText =
            "position:fixed;inset:0;z-index:3000;display:flex;" +
            "align-items:center;justify-content:center;padding:16px;" +
            "background:rgba(0,0,0,.38);box-sizing:border-box";
        var dialog = document.createElement("div");
        dialog.style.cssText =
            "width:100%;max-width:420px;background:var(--background-color,#fff);" +
            "color:var(--text-color,#333);border-radius:6px;" +
            "border:1px solid var(--border-color,#d8dde3);" +
            "padding:22px 24px 18px;text-align:center;box-sizing:border-box";
        var title = document.createElement("div");
        title.textContent = onOk ? "确认卸载扩展" : "提示";
        title.style.cssText =
            "font-size:18px;font-weight:600;margin-bottom:12px";
        var body = document.createElement("div");
        body.textContent = message;
        body.style.cssText =
            "white-space:pre-line;line-height:1.8;margin-bottom:18px";
        var actions = document.createElement("div");
        actions.style.cssText =
            "display:flex;justify-content:center;gap:12px";
        function close() {
            if (overlay.parentNode)
                overlay.parentNode.removeChild(overlay);
        }
        if (onOk) {
            var cancel = document.createElement("button");
            cancel.type = "button";
            cancel.textContent = "取消";
            cancel.style.cssText =
                "min-width:88px;padding:7px 16px;border:1px solid #d8dde3;" +
                "border-radius:4px;background:#fff;cursor:pointer";
            cancel.onclick = close;
            actions.appendChild(cancel);
        }
        var ok = document.createElement("button");
        ok.type = "button";
        ok.textContent = "确定";
        ok.style.cssText =
            "min-width:88px;padding:7px 16px;border:0;border-radius:4px;" +
            "background:#e53935;color:#fff;cursor:pointer";
        ok.onclick = function() {
            close();
            if (typeof onOk === "function")
                onOk();
        };
        actions.appendChild(ok);
        dialog.appendChild(title);
        dialog.appendChild(body);
        dialog.appendChild(actions);
        overlay.appendChild(dialog);
        document.body.appendChild(overlay);
    }

    var button = document.getElementById("pw-server-uninstall-extension");
    if (!button)
        return;
    button.onclick = function() {
        showDialog(
            "将移除节点管理和批量导入扩展，并恢复被修改的页面文件。\n" +
            "无需手动关闭 PassWall，完成后会自动重启服务。\n" +
            "现有节点、分流规则和 PassWall 主配置会保留。",
            function() {
                button.disabled = true;
                button.textContent = "正在卸载…";
                XHR.post('<%=api.url("socks_uninstall")%>', {
                    confirm: "1"
                }, function(x, result) {
                    if (!x || x.status !== 200 || !result || !result.success) {
                        button.disabled = false;
                        button.textContent = "卸载扩展";
                        showDialog(result && result.message || "卸载失败。");
                        return;
                    }
                    showDialog(
                        result.message + (result.backup ? "\n备份：" + result.backup : ""),
                        function() {
                            location.href = '<%=api.url("")%>';
                        }
                    );
                });
            }
        );
    };
})();
</script>
EOF

cat >"$tmp_dir/controller.lua" <<'EOF'
module("luci.controller.passwall_socks_batch", package.seeall)

function index()
    local api = require "luci.passwall.api"
    local socks_entry = entry({
        "admin", "services", api.appname, "socks_batch"
    }, firstchild(), "节点管理", 4)
    socks_entry.dependent = true
    socks_entry.acl_depends = { "luci-app-passwall" }

    local socks_import = entry({
        "admin", "services", api.appname, "socks_batch", "import"
    }, form(api.appname .. "/client/socks_batch"), "批量导入节点", 1)
    socks_import.leaf = true
    socks_import.acl_depends = { "luci-app-passwall" }

    local quick_edit = entry({
        "admin", "services", api.appname, "socks_quick_edit"
    }, call("socks_quick_edit"))
    quick_edit.leaf = true
    quick_edit.acl_depends = { "luci-app-passwall" }

    local block_direct = entry({
        "admin", "services", api.appname, "socks_block_direct"
    }, call("socks_block_direct"))
    block_direct.leaf = true
    block_direct.acl_depends = { "luci-app-passwall" }

    local uninstall = entry({
        "admin", "services", api.appname, "socks_uninstall"
    }, call("socks_uninstall"))
    uninstall.leaf = true
    uninstall.acl_depends = { "luci-app-passwall" }

    local lan_entry = entry({
        "admin", "services", api.appname, "lan_batch"
    }, form(api.appname .. "/client/lan_batch"), "批量导入分流规则", 5)
    lan_entry.leaf = true
    lan_entry.acl_depends = { "luci-app-passwall" }

end

local function reply_json(data, status)
    local http = require "luci.http"
    local json = require "luci.jsonc"
    http.status(status or 200)
    http.prepare_content("application/json")
    http.write(json.stringify(data or {}) or "{}")
end

local function clean(value)
    return tostring(value or ""):match("^%s*(.-)%s*$")
end

function socks_quick_edit()
    local http = require "luci.http"
    local id = clean(http.formvalue("id"))
    if id == "" or not id:match("^[%w_%-]+$") then
        return reply_json({
            success = false,
            message = "节点 ID 无效。"
        }, 400)
    end

    local uci = require("luci.model.uci").cursor()
    local node = uci:get_all("passwall", id)
    if not node or node.protocol ~= "socks" then
        return reply_json({
            success = false,
            message = "未找到 SOCKS5 节点。"
        }, 404)
    end

    if http.getenv("REQUEST_METHOD") ~= "POST" then
        return reply_json({
            success = true,
            id = id,
            remarks = node.remarks or id,
            address = node.address or "",
            port = node.port or "",
            username = node.username or ""
        })
    end

    local remarks = clean(http.formvalue("remarks"))
    local address = clean(http.formvalue("address"))
    local port_text = clean(http.formvalue("port"))
    local port = port_text:match("^%d+$") and tonumber(port_text)
    local username = tostring(http.formvalue("username") or "")
    local password = tostring(http.formvalue("password") or "")

    if remarks == "" then
        remarks = id
    elseif #remarks > 255 then
        return reply_json({
            success = false,
            message = "备注不能超过 255 个字符。"
        }, 400)
    end
    if address == "" or #address > 253 or address:find("%s") then
        return reply_json({
            success = false,
            message = "节点地址无效。"
        }, 400)
    end
    if not port or port < 1 or port > 65535 then
        return reply_json({
            success = false,
            message = "节点端口无效。"
        }, 400)
    end

    local sys = require "luci.sys"
    local backup = "/root/passwall.bak.quickedit." ..
        os.date("%Y%m%d-%H%M%S")
    if sys.call("cp -p /etc/config/passwall " .. backup) ~= 0 then
        return reply_json({
            success = false,
            message = "备份 PassWall 配置失败，本次未修改。"
        }, 500)
    end

    uci:set("passwall", id, "remarks", remarks)
    uci:set("passwall", id, "address", address)
    uci:set("passwall", id, "port", tostring(port))
    uci:set("passwall", id, "username", username)
    if password ~= "" then
        uci:set("passwall", id, "password", password)
    end

    if not uci:commit("passwall") then
        uci:revert("passwall")
        return reply_json({
            success = false,
            message = "保存失败，修改已撤销。"
        }, 500)
    end

    sys.call("(/etc/init.d/passwall restart >/dev/null 2>&1 &)")
    reply_json({
        success = true,
        message = "SOCKS5 节点已保存。",
        id = id
    })
end

function socks_block_direct()
    local http = require "luci.http"
    local uci = require("luci.model.uci").cursor()
    local section = "@global_other[0]"
    local enabled =
        uci:get("passwall", section, "block_direct_on_socks_failure") == "1"

    if http.getenv("REQUEST_METHOD") ~= "POST" then
        return reply_json({
            success = true,
            enabled = enabled
        })
    end

    local want = http.formvalue("enabled") == "1"
    if want == enabled then
        return reply_json({
            success = true,
            enabled = enabled
        })
    end

    local sys = require "luci.sys"
    local backup = "/root/passwall.bak.blockdirect." ..
        os.date("%Y%m%d-%H%M%S")
    if sys.call("cp -p /etc/config/passwall " .. backup) ~= 0 then
        return reply_json({
            success = false,
            message = "备份 PassWall 配置失败，本次未修改。"
        }, 500)
    end

    if want then
        local defaults = {}
        uci:foreach("passwall", "nodes", function(node)
            if node.protocol == "_shunt" then
                defaults[node[".name"]] =
                    node.default_node or ""
                uci:set(
                    "passwall", node[".name"],
                    "default_node", "_blackhole"
                )
            end
        end)
        uci:set(
            "passwall", section,
            "block_direct_defaults",
            require("luci.jsonc").stringify(defaults)
        )
        uci:set(
            "passwall", section,
            "block_direct_on_socks_failure", "1"
        )
    else
        local defaults = {}
        local ok = pcall(function()
            defaults = require("luci.jsonc").parse(
                uci:get(
                    "passwall", section,
                    "block_direct_defaults"
                ) or "{}"
            ) or {}
        end)
        if ok then
            for id, target in pairs(defaults) do
                local node = uci:get_all("passwall", id)
                if node and node.protocol == "_shunt" then
                    if target ~= "" then
                        uci:set(
                            "passwall", id,
                            "default_node", target
                        )
                    else
                        uci:delete(
                            "passwall", id, "default_node"
                        )
                    end
                end
            end
        end
        uci:delete(
            "passwall", section, "block_direct_defaults"
        )
        uci:delete(
            "passwall", section,
            "block_direct_on_socks_failure"
        )
    end

    if not uci:commit("passwall") then
        uci:revert("passwall")
        return reply_json({
            success = false,
            message = "保存失败，修改已撤销。"
        }, 500)
    end

    sys.call("(/etc/init.d/passwall restart >/dev/null 2>&1 &)")
    reply_json({
        success = true,
        enabled = want
    })
end

function socks_uninstall()
    local http = require "luci.http"
    if http.getenv("REQUEST_METHOD") ~= "POST" or
        http.formvalue("confirm") ~= "1" then
        return reply_json({
            success = false,
            message = "需要确认后才能卸载扩展。"
        }, 400)
    end

    local sys = require "luci.sys"
    local package_command
    if sys.call(
        "command -v apk >/dev/null 2>&1 && " ..
        "apk info -e luci-app-passwall-socks5-batch >/dev/null 2>&1"
    ) == 0 then
        package_command = "apk del luci-app-passwall-socks5-batch"
    elseif sys.call(
        "command -v opkg >/dev/null 2>&1 && " ..
        "opkg list-installed luci-app-passwall-socks5-batch | " ..
        "grep -q '^luci-app-passwall-socks5-batch - '"
    ) == 0 then
        package_command = "opkg remove luci-app-passwall-socks5-batch"
    end
    if package_command then
        if sys.call(package_command .. " </dev/null >/dev/null 2>&1") ~= 0 then
            return reply_json({
                success = false,
                message = "包管理器卸载失败，请检查系统日志。"
            }, 500)
        end
        return reply_json({
            success = true,
            message = "扩展已卸载，节点和分流规则已保留。"
        })
    end

    local stamp = os.date("%Y%m%d-%H%M%S")
    local backup_pipe = io.popen(
        "umask 077; mktemp -d /root/passwall-extension.removed." ..
        stamp .. ".XXXXXX"
    )
    local backup_dir = backup_pipe and backup_pipe:read("*l") or ""
    if backup_pipe then
        backup_pipe:close()
    end
    if backup_dir == "" then
        return reply_json({
            success = false,
            message = "无法创建卸载备份目录。"
        }, 500)
    end
    local node_list =
        "/usr/lib/lua/luci/view/passwall/node_list/node_list.htm"
    local nftables = "/usr/share/passwall/nftables.sh"
    local singbox =
        "/usr/lib/lua/luci/passwall/util_sing-box.lua"
    local xray =
        "/usr/lib/lua/luci/passwall/util_xray.lua"
    local server_index =
        "/usr/lib/lua/luci/model/cbi/passwall/server/index.lua"
    local server_uninstall =
        "/usr/lib/lua/luci/view/passwall/server/uninstall_extension.htm"
    local menu_json =
        "/usr/share/luci/menu.d/luci-app-passwall-socks5-batch.json"
    local controller = "/usr/lib/lua/luci/controller/passwall_socks_batch.lua"
    local socks_model =
        "/usr/lib/lua/luci/model/cbi/passwall/client/socks_batch.lua"
    local lan_model =
        "/usr/lib/lua/luci/model/cbi/passwall/client/lan_batch.lua"
    local lan_delete =
        "/usr/lib/lua/luci/model/cbi/passwall/client/lan_delete.lua"
    local socks_delete =
        "/usr/lib/lua/luci/model/cbi/passwall/client/socks_delete.lua"
    local files = {
        controller, socks_model, lan_model, lan_delete, socks_delete,
        node_list, nftables, singbox, xray,
        server_index, server_uninstall, menu_json
    }

    local function quote(value)
        return "'" .. tostring(value):gsub("'", "'\\''") .. "'"
    end

    local function oldest(path)
        local pipe = io.popen(
            "ls -1 " .. path .. " 2>/dev/null | head -n 1"
        )
        local value = pipe and pipe:read("*l") or ""
        if pipe then
            pipe:close()
        end
        return value or ""
    end

    local fs = require "nixio.fs"
    for _, file in ipairs(files) do
        if fs.access(file) then
            if sys.call(
                "cp -p " .. quote(file) .. " " ..
                quote(backup_dir) .. "/"
            ) ~= 0 then
                return reply_json({
                    success = false,
                    message = "卸载备份失败，扩展未移除。"
                }, 500)
            end
        end
    end
    local state_file =
        "/root/passwall-socks5-batch.install-state"
    if fs.access(state_file) then
        if sys.call(
            "cp -p " .. quote(state_file) .. " " ..
            quote(backup_dir) .. "/"
        ) ~= 0 then
            return reply_json({
                success = false,
                message = "卸载状态备份失败，扩展未移除。"
            }, 500)
        end
    end

    local restores = {
        { controller, controller .. ".bak.*",
            'module("luci.controller.passwall_socks_batch"' },
        { socks_model, socks_model .. ".bak.*", 'SimpleForm("socks_batch"' },
        { lan_model, lan_model .. ".bak.*", 'SimpleForm("lan_batch"' },
        { lan_delete, lan_delete .. ".bak.*", 'SimpleForm("lan_delete"' },
        { socks_delete, socks_delete .. ".bak.*", 'SimpleForm("socks_delete"' },
        { server_uninstall, server_uninstall .. ".bak.*",
            "pw-server-uninstall-extension" },
        { menu_json, menu_json .. ".bak.*",
            '"admin/services/passwall/socks_batch"' },
        { node_list, node_list .. ".bak.oneclick.*" },
        { nftables, nftables .. ".bak.oneclick.*" },
        { singbox, singbox .. ".bak.oneclick.*" },
        { xray, xray .. ".bak.lanbatch.*" },
        { server_index, server_index .. ".bak.uninstallext.*" }
    }
    local original_suffix = ".bak.passwall-socks5-batch.original"
    for _, item in ipairs(restores) do
        local original = item[1] .. original_suffix
        local command
        if fs.access(original) then
            command = "cp -p " .. quote(original) .. " " .. quote(item[1])
        elseif fs.access(original .. ".absent") then
            command = "rm -f " .. quote(item[1])
        else
            local backup = oldest(item[2])
            if backup ~= "" then
                if item[3] and sys.call(
                    "grep -Fq " .. quote(item[3]) .. " " .. quote(backup)
                ) == 0 then
                    if not fs.access(item[1]) or sys.call(
                        "grep -Fq " .. quote(item[3]) .. " " .. quote(item[1])
                    ) == 0 then
                        command = "rm -f " .. quote(item[1])
                    end
                else
                    command = "cp -p " .. quote(backup) .. " " .. quote(item[1])
                end
            elseif item[3] and fs.access(item[1]) and sys.call(
                "grep -Fq " .. quote(item[3]) .. " " .. quote(item[1])
            ) == 0 then
                command = "rm -f " .. quote(item[1])
            end
        end
        if command and sys.call(command) ~= 0 then
            return reply_json({
                success = false,
                message = "恢复原始 PassWall 文件失败，卸载已停止。"
            }, 500)
        end
    end
    if not fs.access(server_index .. original_suffix) and
        not fs.access(server_index .. original_suffix .. ".absent") and
        sys.call(
            "if grep -Fq '/server/uninstall_extension' " ..
            quote(server_index) .. "; then " ..
            "sed -i '\\#/server/uninstall_extension#d' " ..
            quote(server_index) .. "; fi"
        ) ~= 0 then
        return reply_json({
            success = false,
            message = "恢复 PassWall 服务端页面失败，卸载已停止。"
        }, 500)
    end
    for _, item in ipairs(restores) do
        local original = item[1] .. original_suffix
        if sys.call(
            "rm -f " .. quote(original) .. " " .. quote(original .. ".absent")
        ) ~= 0 then
            return reply_json({
                success = false,
                message = "清理卸载状态失败，请检查备份目录。"
            }, 500)
        end
    end
    if fs.access(state_file) then
        if sys.call("rm -f " .. quote(state_file)) ~= 0 then
            return reply_json({
                success = false,
                message = "清理卸载状态失败，请检查备份目录。"
            }, 500)
        end
    end
    if sys.call(
        "touch " .. quote("/root/passwall-socks5-batch.uninstalled")
    ) ~= 0 then
        return reply_json({
            success = false,
            message = "记录卸载状态失败，请检查备份目录。"
        }, 500)
    end

    sys.call(
        "for f in /tmp/luci-indexcache*; do " ..
        "[ -f \"$f\" ] && rm -f \"$f\"; done"
    )
    sys.call("(/etc/init.d/uhttpd reload >/dev/null 2>&1 &)")
    sys.call("(/etc/init.d/passwall restart >/dev/null 2>&1 &)")
    reply_json({
        success = true,
        message = "扩展已卸载，节点和分流规则已保留。",
        backup = backup_dir
    })
end
EOF

cat >"$tmp_dir/model.lua" <<'EOF'
