PW_B64_9

    # 插件设置功能已删除，确保旧文件不残留
    rm -f /usr/lib/lua/luci/view/passwall/plugin_settings.htm

    # uci 默认值：断网保护 + 分流规则的 DNS检测 开关（仅对有源 IP 的规则）
    uci -q set passwall.@global_other[0].block_direct_on_socks_failure=1
    _pw_gnode=$(uci -q get passwall.@global[0].node)
    if [ -n "$_pw_gnode" ]; then
        for _pw_rule in $(uci show passwall 2>/dev/null | grep '=shunt_rules' | cut -d. -f2 | cut -d= -f1); do
            _pw_src=$(uci -q get "passwall.$_pw_rule.source")
            [ -n "$_pw_src" ] && uci -q set "passwall.$_pw_gnode.${_pw_rule}_dns_check=1"
        done
    fi
    uci -q commit passwall

    # DNS 接管守护进程
    /etc/init.d/passwall-dnscheck enable >/dev/null 2>&1 || true
    /usr/bin/passwall-dnscheck-gen >/dev/null 2>&1 || true
    /etc/init.d/passwall-dnscheck restart >/dev/null 2>&1 || true
    /etc/init.d/passwall restart >/dev/null 2>&1 || true

    # 清理 LuCI 缓存
    for _pw_cache in /tmp/luci-indexcache*; do
        [ -f "$_pw_cache" ] && rm -f "$_pw_cache"
    done
    rm -rf /tmp/luci-modulecache
    (sleep 2; /etc/init.d/uhttpd reload) </dev/null >/dev/null 2>&1 &

    echo "更新完成：DNS检测 / IP可用性检测 / 分页 / 弹窗 / 快速更改节点 等已同步。"
}

install_update_assets
write_install_state
release_lock

echo "版本：$SCRIPT_VERSION"
echo "状态文件：$INSTALL_STATE"
echo "全部完成。"

############################################################################
# 更新段（主开关统一控制）：PassWall 主开关关闭时，DNS 接管守护进程不启动；
#   打开主开关时自动启动并加载 DNS检测 规则。同时修正 dns_leak_remove_uci。
