PW_MB_2

    # 有源 IP 的分流规则默认开启 DNS检测，由 PassWall 主开关统一启停
    _mb_gnode=$(uci -q get passwall.@global[0].node)
    if [ -n "$_mb_gnode" ]; then
        for _mb_rule in $(uci show passwall 2>/dev/null | grep '=shunt_rules' | cut -d. -f2 | cut -d= -f1); do
            _mb_src=$(uci -q get "passwall.$_mb_rule.source")
            [ -n "$_mb_src" ] && uci -q set "passwall.$_mb_gnode.${_mb_rule}_dns_check=1"
        done
    fi
    uci -q commit passwall

    # 主开关默认关闭：安装后不自动启用代理与 DNS 接管，由用户手动打开主开关
    uci -q set passwall.@global[0].enabled=0
    uci -q set passwall.@global_other[0].socks_enabled=0
    uci -q commit passwall
    # 立即停掉正在运行的代理与 nft 规则，保证安装后处于“主开关关闭”状态
    /etc/init.d/passwall stop >/dev/null 2>&1 || true
    /etc/init.d/passwall-dnscheck enable >/dev/null 2>&1 || true
    /etc/init.d/passwall-dnscheck stop >/dev/null 2>&1 || true

    for _mb_cache in /tmp/luci-indexcache*; do
        [ -f "$_mb_cache" ] && rm -f "$_mb_cache"
    done
    rm -rf /tmp/luci-modulecache
    (sleep 2; /etc/init.d/uhttpd reload) </dev/null >/dev/null 2>&1 &

    echo "主开关默认已关闭：打开 PassWall 主开关后，DNS检测等功能才会启用。"
}

